-- ==========================================
-- SEED DATA: Datos oficiales para el sistema
-- ==========================================

-- 1. Insertar Tiendas (79 locales de la Sierra)
ON CONFLICT (id) DO UPDATE SET
  nombre = EXCLUDED.nombre,
  ciudad = EXCLUDED.ciudad,
  direccion = EXCLUDED.direccion,
  unidad = EXCLUDED.unidad,
  supervisor_nombre = EXCLUDED.supervisor_nombre;

-- 2. Insertar Usuarios (Gerencia, Supervisores, Técnicos y Locales)
ON CONFLICT (id) DO UPDATE SET
  nombre = EXCLUDED.nombre,
  correo = EXCLUDED.correo,
  usuario = EXCLUDED.usuario,
  contrasena = EXCLUDED.contrasena,
  rol = EXCLUDED.rol,
  tienda_id = EXCLUDED.tienda_id,
  supervisor_tiendas = EXCLUDED.supervisor_tiendas,
  estado = EXCLUDED.estado;

-- 3. Insertar Casos Iniciales de Demostración
ON CONFLICT (id) DO UPDATE SET
  tienda_id = EXCLUDED.tienda_id,
  creado_por = EXCLUDED.creado_por,
  categoria = EXCLUDED.categoria,
  descripcion = EXCLUDED.descripcion,
  prioridad_nivel = EXCLUDED.prioridad_nivel,
  estado = EXCLUDED.estado,
  tecnico_asignado_id = EXCLUDED.tecnico_asignado_id;
